const staticData = $getWorkflowStaticData('global');
const sentEmails = staticData.sentEmails || [];
const now = new Date();

const pending = sentEmails.filter(record => {
  if (!record.next_follow_up) return false;
  const followUpDate = new Date(record.next_follow_up);
  return followUpDate <= now && record.sequence_step < (record.follow_up_days?.length || 3);
});

if (pending.length === 0) return [];

return pending.map(record => ({
  json: { ...record, sequence_step: record.sequence_step + 1 }
}));

const record = $input.all()[0].json;
const step = record.sequence_step;
const firstName = record.lead_name.split(' ')[0];

const followUpTemplates = {
  2: {
    subject: `Re: ${record.subject}`,
    body: `Sehr geehrte/r ${firstName},\n\nich wollte kurz nachfassen — hatten Sie Gelegenheit, meine letzte Nachricht zu lesen?\n\nIch bin überzeugt, dass Oracle Cloud Infrastructure für ${record.company} einen echten Unterschied machen kann:\n- Kostenoptimierung Ihrer Cloud-Ausgaben\n- EU Sovereign Cloud für Compliance\n- Multicloud-Flexibilität\n\nWann passt es Ihnen für ein kurzes 15-Minuten-Gespräch?\n\nMit freundlichen Grüßen`
  },
  3: {
    subject: `Re: ${record.subject}`,
    body: `Sehr geehrte/r ${firstName},\n\ndies ist meine letzte Nachricht zu diesem Thema. Ich verstehe, dass Sie beschäftigt sind.\n\nFalls Cloud-Infrastruktur oder Multicloud-Strategien in Zukunft für ${record.company} relevant werden, stehe ich Ihnen jederzeit zur Verfügung.\n\nDarf ich Sie in 3 Monaten nochmals kontaktieren?\n\nMit freundlichen Grüßen`
  }
};

const template = followUpTemplates[step] || followUpTemplates[3];

return [{
  json: {
    email_to: record.email,
    email_subject: template.subject,
    email_body: template.body,
    lead: { full_name: record.lead_name, email: record.email },
    company_data: { name: record.company },
    campaign: { max_emails_per_day: 30 },
    sequence_step: step,
    original_record: record
  }
}];

const staticData = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);

if (!staticData.followUpEmailsSent) staticData.followUpEmailsSent = {};
if (!staticData.followUpEmailsSent[today]) staticData.followUpEmailsSent[today] = 0;

const limit = $input.all()[0].json.campaign.max_emails_per_day || 30;
const sentToday = staticData.followUpEmailsSent[today];

if (sentToday >= limit) {
  return [];
}

staticData.followUpEmailsSent[today] = sentToday + 1;
return $input.all();

const staticData = $getWorkflowStaticData('global');
const sentEmails = staticData.sentEmails || [];
const currentRecord = $input.all()[0].json.original_record;
const currentStep = $input.all()[0].json.sequence_step;

// Find and update the original record
for (let i = 0; i < sentEmails.length; i++) {
  if (sentEmails[i].email === currentRecord.email && sentEmails[i].sent_at === currentRecord.sent_at) {
    sentEmails[i].sequence_step = currentStep;

    const followUpDays = sentEmails[i].follow_up_days || [3, 7, 14];
    if (currentStep < followUpDays.length) {
      const daysUntil = followUpDays[currentStep];
      sentEmails[i].next_follow_up = new Date(Date.now() + daysUntil * 86400000).toISOString();
    } else {
      sentEmails[i].next_follow_up = null;
      sentEmails[i].sequence_completed = true;
    }

    sentEmails[i].last_follow_up_at = new Date().toISOString();
    break;
  }
}

staticData.sentEmails = sentEmails;

return [{
  json: {
    status: 'follow_up_sent',
    email: currentRecord.email,
    lead_name: currentRecord.lead_name,
    company: currentRecord.company,
    sequence_step: currentStep,
    sent_at: new Date().toISOString()
  }
}];
